create schema if not exists chronos_private;
revoke all on schema chronos_private from public, anon, authenticated;

create table public.learners (id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table public.content_lessons (id text primary key, snapshot_version text not null, published_at timestamptz, unique(id,snapshot_version));
create table public.journeys (id text primary key, snapshot_version text not null);
create table public.journey_entries (id text primary key, journey_id text not null references public.journeys(id), lesson_id text not null references public.content_lessons(id), position integer not null check(position>=0), required boolean not null default true, unique(journey_id,position));
create table public.knowledge_cards (id text primary key, snapshot_version text not null);
create table public.card_unlocks (lesson_id text primary key references public.content_lessons(id), card_id text not null references public.knowledge_cards(id));
create table public.legacy_id_aliases (legacy_id text primary key, canonical_id text not null, entity_kind text not null check(entity_kind in('lesson','card')), semantic_equivalence_approved boolean not null default false, review_note text not null);
create table public.lesson_progress (learner_id uuid not null references public.learners(id) on delete cascade, lesson_id text not null references public.content_lessons(id), status text not null default 'in_progress' check(status in('in_progress','completed')), started_at timestamptz not null default now(), completed_at timestamptz, primary key(learner_id,lesson_id), check((status='completed')=(completed_at is not null)));
create table public.section_resume_state (learner_id uuid not null, lesson_id text not null, section_id text not null, updated_at timestamptz not null default now(), primary key(learner_id,lesson_id), foreign key(learner_id,lesson_id) references public.lesson_progress(learner_id,lesson_id) on delete cascade);
create table public.understanding_prompt_attempts (id bigint generated always as identity primary key, learner_id uuid not null, lesson_id text not null, prompt_id text not null, response jsonb not null, attempted_at timestamptz not null default now(), foreign key(learner_id,lesson_id) references public.lesson_progress(learner_id,lesson_id) on delete cascade);
create index prompt_attempts_completion_idx on public.understanding_prompt_attempts(learner_id,lesson_id,prompt_id);
create table public.completion_commands (learner_id uuid not null references public.learners(id) on delete cascade, idempotency_key text not null, lesson_id text not null references public.content_lessons(id), result jsonb, created_at timestamptz not null default now(), primary key(learner_id,idempotency_key));
create table public.card_ownership (learner_id uuid not null references public.learners(id) on delete cascade, card_id text not null references public.knowledge_cards(id), acquired_at timestamptz not null default now(), source_lesson_id text not null references public.content_lessons(id), primary key(learner_id,card_id));

